            /**
             * Changed Files
             * @default []
             */
            changed_files: string[];
            /**
             * Tests Run
             * @default []
             */
            tests_run: string[];
            /**
             * Started At
             * Format: date-time
             */
            started_at: string;
            /** Ended At */
            ended_at?: string | null;
            /** Agent Profile */
            agent_profile?: string | null;
            /** Harness */
            harness?: string | null;
            /** Provider */
            provider?: string | null;
            /** Model */
            model?: string | null;
